def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    for x in range(2, num):
        if num % x == 0:
            return False
    else:
        return True


def first_n_primes(n):
    """Generate the first n prime numbers."""
    if not 0 < n <= 200:
        raise ValueError("n must be between 1 and 200")
    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
