        self.val = val
        self.left = left
        self.right = right

def sumOfLeftLeaves(self, root, is_left=False):
    if not root:
        return 0
    if not root.left and not root.right and is_left:
        return root.val
    return self.sumOfLeftLeaves(root.left, True) + self.sumOfLeftLeaves(root.right, False)
