```C++
#include<iostream>
#include<vector>
using namespace std;

pair<double, double> findDiagonalProducts(vector<vector<double>>& mat) {
    int n = mat.size(); // matrix size

    double prod_main = 1.0, prod_sec = 1.0;

    for (int i = 0; i < n; i++) {
        // calculating product of main diagonal
        prod_main *= mat[i][i];

        // calculating product of secondary diagonal
        prod_sec *= mat[i][n-i-1];
    }

    // return both diagonal products as pair
    return {prod_main, prod_sec};
}

int main() {
    vector<vector<double>> mat = {{2, 1, 3, 5, 4}, {4, 5, 6, 4, 2}, {7, 8, 9, 1, 3}, {1, 2, 3, 4, 7}, {5, 6, 7, 8, 9}};

    pair<double, double> diagonalProducts = findDiagonalProducts(mat);
    cout << "Product of elements of main diagonal: " << diagonalProducts.first << endl;
    cout << "Product of elements of second diagonal: " << diagonalProducts.second << endl;

    return 0;
}
``` 

