```java
import java.util.HashMap;
import java.util.Map;

public class WordFrequency {
    public static void main(String[] args) {
        String[] dictionary = {"apple", "banana", "orange", "grape"};
        String sentence1 = "apple banana aple orange bannana grape";
        String sentence2 = "aplle bananna apple ornge banana grape";
        Map<String, Integer> wordCounts1 = findWordFrequencies(sentence1, dictionary);
        Map<String, Integer> wordCounts2 = findWordFrequencies(sentence2, dictionary);

        printWordCounts(wordCounts1);
        printWordCounts(wordCounts2);
    }

    private static Map<String, Integer> findWordFrequencies(String sentence, String[] dictionary) {
        Map<String, Integer> wordCounts = new HashMap<>();
        for (String word : sentence.split(" ")) {
            String correctWord = getClosestWord(word, dictionary);
            wordCounts.put(correctWord, wordCounts.getOrDefault(correctWord, 0) + 1);
        }
        return wordCounts;
    }

    private static String getClosestWord(String input, String[] dictionary) {
        int minDistance = Integer.MAX_VALUE;
        String closestWord = null;
        for (String word : dictionary) {
            int distance = calculateLevenshteinDistance(input, word);
            if (distance < minDistance) {
                minDistance = distance;
                closestWord = word;
            }
