import json

def traverse_json(json_obj, key_path = ''):
    if isinstance(json_obj, dict):
        for k, v in json_obj.items():
            new_key_path = f"{key_path}.{k}" if key_path else k
            traverse_json(v, new_key_path)
    elif isinstance(json_obj, list):
