Below are two Python sub-routines that perform your request:

```python
import cmath

def perfect_square(n):
    return n == int(cmath.sqrt(n).real)**2

def digit_sum(n):
    return sum(map(int, str(n).replace('.', '').replace('-', '')))

def check_real(startnum, endnum):
    count = 0
    for i in range(startnum, endnum+1):
        if perfect_square(i) and perfect_square(digit_sum(i)):
            count += 1
    return count

def check_complex(startnum, endnum):
    count = 0
    startnum = complex(startnum)
    endnum = complex(endnum)
    re = startnum.real
    while re <= endnum.real:
        im = startnum.imag
        while im <= endnum.imag:
            num = complex(re, im)
            if perfect_square(digit_sum(num.real)) and perfect_square(digit_sum(num.imag)):
                count += 1
            im += 1
        re += 1
    return count
```

