```cpp
#include <iostream>
#include <vector>
#include <random>
#include <algorithm>
#include <exception>

std::vector<int> generateRandom(int begin, int end, int count) 
{
    // check if the range is not valid
    if (end < begin || end - begin < count)
    {
        throw std::invalid_argument("Invalid range provided.");
    }

    // Create a vector that holds numbers within given range
    std::vector<int> numbers;
    numbers.reserve(end - begin + 1);
    for (int i = begin; i <= end; ++i) 
    {
        numbers.push_back(i);
    }

    // Create a random device
    std::random_device rd;
    std::mt19937 g(rd());

    // Shuffle the numbers
    std::shuffle(numbers.begin(), numbers.end(), g);

    // Reduce the size of the vector to the desired count
    numbers.resize(count);

    return numbers;
}

int main()
{
    try 
    {
        std::vector<int> numbers = generateRandom(10, 50, 5);
        for (auto &number: numbers) 
        {
            std::cout << number << std::endl;
        }
    } 
    catch (const std::exception& e) 
    {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}
