def bubble_sort(l):
    n = len(l)
    for i in range(n):
        for j in range(0, n - i - 1):
            if l[j] > l[j + 1] :
                l[j], l[j + 1] = l[j + 1], l[j]
    return l

def average(l):
    return sum(l) / len(l)

def solve(input_list):
