import java.util.*;

public class Main {
    public static int countPermutations(List<String> items){
        Set<List<String>> uniquePermutations = new HashSet<>();
        permutations(items, 0, uniquePermutations);
        return uniquePermutations.size();
    }

    private static void permutations(List<String> array, int i, Set<List<String>> set){
        if(i == array.size()){
            set.add(array);
            return;
        }
        for(int j = i; j<array.size(); j++){
            Collections.swap(array, i, j);
            permutations(array, i+1, set);
            Collections.swap(array, i, j);
        }
    }
}
