#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct Groups{
    char** items;
    int current_size;
    int max_size;
} Groups;

void initGroups(Groups* g, int size){
    g->items = (char**) malloc(size * sizeof(char*));
    g->current_size = 0;
    g->max_size = size;
}

void addGroup(Groups* g, char* item){
    if(g->current_size == g->max_size){
        g->max_size *= 2;
        g->items = (char**) realloc(g->items, g->max_size * sizeof(char*));
    }
    g->items[g->current_size] = (char*) malloc((strlen(item) + 1) * sizeof(char));
    strcpy(g->items[g->current_size], item);
    g->current_size++;
}

void separateAndCountParenGroups(char* paren_string, Groups* groups){
    char* token = strtok(paren_string, " ");
    while(token != NULL){
        if(strlen(token) >= 2){
            int count = 0;
            char group[100];     //assumes a group will not be more than 100 characters long
            int group_index = 0;
            for(int i=0; i<strlen(token); i++){
                if(token[i] == '(' || token[i] == ')'){
                    count++;
                    group[group_index++] = token[i];
                }
            }
            group[group_index] = '\0';  

            int matched_count = 0;
            for(int i=0; i<strlen(group); i += 2){
               if(group[i] == '(' && group[i+1] == ')') matched_count += 2;
            }

            if(matched_count == count){
                char temp[100];   //assumes a group will not be more than 100 characters long
                sprintf(temp, "%d:%s", count, group);
                addGroup(groups, temp);
            }
        }
        token = strtok(NULL, " ");
    }
}

