import java.util.*;
import java.util.stream.Stream;

class Solution {
    public Optional<String> secondLongest(String[] arr) {
        return Stream.of(arr)
            .distinct()
            .sorted((str1, str2) -> str2.length() - str1.length())
            .skip(1)
            .findFirst();
    }
}
```

