public class PrimeFactors {
    public static void main(String[] args) {
        int number = 36; // Insert your number here.

        Set<Integer> factors = primeFactors(number);

        System.out.println("Prime factors of " + number + " are: " + factors);
        System.out.println("Count of unique prime factors: " + factors.size());
