    private static Set<Integer> primeFactors(int number) {
        Set<Integer> factors = new HashSet<>();

        for (int i = 2; i <= number; i++) {
            while (number % i == 0) {
                factors.add(i);
                number /= i;
            }
        }

        return factors;
    }
}
